# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM\'DA AKRABALIK İLİŞKİLERİ: SILA-İ RAHİM VE KAT\'-I RAHİM</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#166534">SILA-İ RAHİM (BAĞLARI YAŞATMAK)</text>\n  <text x="34" y="88" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">Tanım:</tspan> Akrabaları ziyaret etmek, hâl-hatır sormak,</text>\n  <text x="44" y="104" font-size="10.4" fill="#14532d">iyi ve kötü günde yanlarında olup destek vermektir.</text>\n  <text x="34" y="126" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">Kur\'an Hükmü (Nahl, 16/90):</tspan> Adalet ve ihsanla</text>\n  <text x="44" y="142" font-size="10.4" fill="#14532d">birlikte yakınlara (akrabalara) yardım emredilmiştir.</text>\n  <text x="34" y="164" font-size="10.6" fill="#14532d">• <tspan font-weight="bold">Bireysel ve Toplumsal Meyveleri:</tspan></text>\n  <text x="44" y="180" font-size="10.4" fill="#14532d">Rızkın bereketlenmesi, ömrün hayırlı ve huzurlu</text>\n  <text x="44" y="196" font-size="10.4" fill="#14532d">olması, yalnızlığın önlenmesi ve aile dayanışması.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#991b1b">GERÇEK SILA-İ RAHİM VE KAT\'-I RAHİM UYARISI</text>\n  <text x="370" y="88" font-size="10.6" font-weight="bold" fill="#b91c1c">• Gerçek Sıla-i Rahim Yapan (Vâsıl):</text>\n  <text x="380" y="104" font-size="10.4" fill="#7f1d1d">Yalnızca gelene gitmek değil; akrabalık bağını</text>\n  <text x="380" y="120" font-size="10.4" fill="#7f1d1d">koparan yakınlarıyla bile yeniden bağ kurmaktır.</text>\n  <text x="370" y="144" font-size="10.6" font-weight="bold" fill="#b91c1c">• Kat\'-ı Rahim (Akrabalık Bağını Koparmak):</text>\n  <text x="380" y="160" font-size="10.4" fill="#7f1d1d">Akrabalarla küs kalmak ve yardımı kesmektir;</text>\n  <text x="380" y="176" font-size="10.4" fill="#7f1d1d">toplumsal çözülmeye yol açan ağır bir sorumluluktur.</text>\n  <text x="370" y="200" font-size="10.4" font-weight="bold" fill="#991b1b">• Yoksul akrabaya verilen sadaka çift ecir kazandırır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">«Rızkının genişletilmesini ve ömrünün bereketlendirilmesini isteyen akrabalık bağlarını gözetsin.» (Buhârî, Edeb, 12)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM AHLAKINDA KOMŞULUK SINIFLANDIRMASI VE KOMŞU HAKLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#1e40af">HAKLARINA GÖRE ÜÇ TÜRLÜ KOMŞU</text>\n  <text x="34" y="90" font-size="10.8" font-weight="bold" fill="#1d4ed8">1. Üç Hakkı Olan Komşu:</text>\n  <text x="44" y="106" font-size="10.4" fill="#1e3a8a">Hem akraba hem Müslüman komşu (Komşuluk hakkı +</text>\n  <text x="44" y="120" font-size="10.4" fill="#1e3a8a">Akrabalık hakkı + İslam kardeşliği hakkı).</text>\n  <text x="34" y="144" font-size="10.8" font-weight="bold" fill="#1d4ed8">2. İki Hakkı Olan Komşu:</text>\n  <text x="44" y="160" font-size="10.4" fill="#1e3a8a">Akraba olmayan Müslüman komşu (Komşuluk hakkı +</text>\n  <text x="44" y="174" font-size="10.4" fill="#1e3a8a">İslam kardeşliği hakkı).</text>\n  <text x="34" y="196" font-size="10.8" font-weight="bold" fill="#1d4ed8">3. Bir Hakkı Olan Komşu (Gayrimüslim Komşu):</text>\n  <text x="44" y="210" font-size="10.4" fill="#1e3a8a">İnancı ne olursa olsun komşuluk ve insanlık hakkı vardır.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#854d0e">BAŞLICA KOMŞULUK SORUMLULUKLARI</text>\n  <text x="370" y="88" font-size="10.6" fill="#713f12">• Komşuya elinden ve dilinden güven vermek; gürültü,</text>\n  <text x="380" y="104" font-size="10.4" fill="#713f12">çöp veya koku ile rahatsızlık vermemek.</text>\n  <text x="370" y="126" font-size="10.6" fill="#713f12">• Karşılaşınca selamlaşmak ve güler yüz göstermek.</text>\n  <text x="370" y="148" font-size="10.6" fill="#713f12">• Hastalandığında ziyaret etmek, cenazesine katılmak.</text>\n  <text x="370" y="170" font-size="10.6" fill="#713f12">• Pişen yemekten ikram etmek ve açlığını gözetmek.</text>\n  <text x="370" y="192" font-size="10.6" fill="#713f12">• Komşunun ev ve aile mahremiyetini korumak,</text>\n  <text x="380" y="206" font-size="10.4" fill="#713f12">yokluğunda malına ve emanetine sahip çıkmak.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">«Cebrâil bana komşuyu o kadar tavsiye etti ki, komşuyu komşuya mirasçı kılacak zannettim.» (Buhârî, Edeb, 28)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">İSLAM\'DA TOPLUMSAL DAYANIŞMA HALKALARI VE İNFAK ADABI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#6b21a8">YARDIMLAŞMA ÖNCELİK HALKALARI (BAKARA, 215)</text>\n  <text x="34" y="90" font-size="10.8" font-weight="bold" fill="#7e22ce">1. Çekirdek Aile ve Anne Baba (Birru\'l-vâlideyn)</text>\n  <text x="34" y="112" font-size="10.8" font-weight="bold" fill="#7e22ce">2. Yakın ve Uzak Akrabalar (Sıla-i Rahim)</text>\n  <text x="34" y="134" font-size="10.8" font-weight="bold" fill="#7e22ce">3. Yakın ve Uzak Komşular (Komşu Hakkı)</text>\n  <text x="34" y="156" font-size="10.8" font-weight="bold" fill="#7e22ce">4. Yetimler, Yoksullar, Yaşlılar ve Yolda Kalmışlar</text>\n  <text x="34" y="180" font-size="10.4" fill="#581c87">• <tspan font-weight="bold">Teâvün (Mâide, 5/2):</tspan> İyilik ve takva üzere</text>\n  <text x="44" y="196" font-size="10.4" fill="#581c87">yardımlaşmak; günah ve zulümde yardımlaşmamak.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.2" font-weight="bold" fill="#9a3412">İNFAK VE YARDIMLAŞMANIN AHLAKİ İLKELERİ</text>\n  <text x="370" y="88" font-size="10.6" fill="#7c2d12">• <tspan font-weight="bold">İhlas (Allah Rızası):</tspan> Gösterişten (riya) uzak durmak.</text>\n  <text x="370" y="110" font-size="10.6" fill="#7c2d12">• <tspan font-weight="bold">Başa Kakmamak (Bakara, 264):</tspan> Yapılan iyiliği</text>\n  <text x="380" y="126" font-size="10.4" fill="#7c2d12">söyleyerek ihtiyaç sahibinin onurunu incitmemek.</text>\n  <text x="370" y="148" font-size="10.6" fill="#7c2d12">• <tspan font-weight="bold">Temiz ve Helal Maldan Vermek (Bakara, 267):</tspan></text>\n  <text x="380" y="164" font-size="10.4" fill="#7c2d12">Kendimizin beğenmeyeceği kalitesiz malı vermemek.</text>\n  <text x="370" y="186" font-size="10.6" fill="#7c2d12">• <tspan font-weight="bold">Gizlilik ve Nezaket:</tspan> Sağ elin verdiğini sol elin</text>\n  <text x="380" y="202" font-size="10.4" fill="#7c2d12">görmeyeceği şekilde mahremiyeti korumak.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">«İyilik ve takva üzere yardımlaşın; günah ve düşmanlık üzere yardımlaşmayın.» (Mâide, 5/2)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
